CREATE TABLE IF NOT EXISTS articles(id INTEGER PRIMARY KEY AUTOINCREMENT,slug TEXT NOT NULL UNIQUE,section TEXT NOT NULL,language TEXT NOT NULL,title TEXT NOT NULL,summary TEXT NOT NULL,body TEXT NOT NULL,sources_json TEXT NOT NULL DEFAULT '[]',status TEXT NOT NULL DEFAULT 'PUBLISHED',image_url TEXT,image_alt TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);CREATE INDEX IF NOT EXISTS idx_articles_section_status ON articles(section,status,updated_at DESC);CREATE INDEX IF NOT EXISTS idx_articles_language_status ON articles(language,status,updated_at DESC);CREATE TABLE IF NOT EXISTS contributions(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,body TEXT NOT NULL,source TEXT,section TEXT NOT NULL DEFAULT 'world',status TEXT NOT NULL DEFAULT 'PENDING',reviewer_note TEXT,created_at TEXT NOT NULL,reviewed_at TEXT);CREATE INDEX IF NOT EXISTS idx_contributions_status ON contributions(status,created_at DESC);CREATE TABLE IF NOT EXISTS searches(id INTEGER PRIMARY KEY AUTOINCREMENT,query TEXT NOT NULL,language TEXT NOT NULL,intent TEXT,status TEXT NOT NULL,source_count INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL);CREATE TABLE IF NOT EXISTS saved_articles(visitor_id TEXT NOT NULL,slug TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(visitor_id,slug));CREATE TABLE IF NOT EXISTS analytics(id INTEGER PRIMARY KEY AUTOINCREMENT,visitor_hash TEXT NOT NULL,event TEXT NOT NULL,path TEXT NOT NULL,language TEXT NOT NULL,created_at TEXT NOT NULL);CREATE TABLE IF NOT EXISTS runtime_events(id INTEGER PRIMARY KEY AUTOINCREMENT,level TEXT NOT NULL,kind TEXT NOT NULL,message TEXT NOT NULL,created_at TEXT NOT NULL);CREATE TABLE IF NOT EXISTS repair_jobs(id INTEGER PRIMARY KEY AUTOINCREMENT,signature TEXT NOT NULL UNIQUE,status TEXT NOT NULL DEFAULT 'DETECTED',diagnosis TEXT,action TEXT,verification TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);